        .api-btn-confirm:hover { background-color: rgba(160, 255, 128, 0.1); box-shadow: 0 0 15px var(--accent-lime); }
        .api-btn-cancel { border-color: var(--accent-red); color: var(--accent-red); }
        .api-btn-cancel:hover { background-color: rgba(255, 80, 96, 0.1); box-shadow: 0 0 15px var(--accent-red); }

        /* --- Modal Styles --- */
        .modal-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(10, 5, 20, 0.8); backdrop-filter: var(--backdrop-blur); -webkit-backdrop-filter: var(--backdrop-blur); display: none; justify-content: center; align-items: center; z-index: 1000; animation: fadeIn-Up 0.4s ease forwards; }
        .modal-content {
            background: var(--bg-glass); border: 1px solid var(--border-highlight);
            border-radius: 12px; padding: 25px; width: 90%; max-width: 500px;
            display: flex; flex-direction: column; max-height: 90vh;
            box-shadow: 0 0 30px rgba(96, 208, 255, 0.5);
        }
        .modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; flex-shrink: 0; }
        .modal-title { font-family: var(--font-tech); font-size: 1.4em; color: var(--accent-pink); font-weight: bold; text-shadow: var(--shadow-glow-pink); }
        .modal-close-btn { background: none; border: none; font-size: 1.8em; color: var(--text-muted); cursor: pointer; transition: all 0.2s; }
        .modal-close-btn:hover { color: var(--accent-red); transform: rotate(90deg); }
        .modal-body { flex-grow: 1; overflow-y: auto; padding-right: 10px; }
        .modal-footer { margin-top: 20px; flex-shrink: 0; display: flex; justify-content: flex-end; gap: 10px; }

        .form-group { margin-bottom: 15px; }
        .form-group label { display: block; margin-bottom: 6px; color: var(--text-secondary); font-weight: 500; font-size: 0.9em; text-transform: uppercase; }
        .form-group input, .form-group textarea {
            width: 100%; box-sizing: border-box; background: var(--bg-card);
            border: 1px solid var(--border-color); border-radius: 6px;
            padding: 10px; color: var(--text-primary); font-family: var(--font-main);
            transition: all 0.2s ease;
        }
        .form-group input:focus, .form-group textarea:focus { border-color: var(--border-highlight); box-shadow: 0 0 10px rgba(96, 208, 255, 0.5); outline: none; }
        .form-group textarea { resize: vertical; min-height: 80px; }

        /* --- Shop Styles --- */
        .shop-nav { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 15px; padding-bottom: 10px; border-bottom: 1px solid var(--border-color); }
        .shop-nav-btn {
            background: var(--bg-card); border: 1px solid var(--border-color);
            color: var(--text-secondary); padding: 5px 12px; border-radius: 6px;
            cursor: pointer; transition: all 0.2s ease; font-family: var(--font-tech);
        }
        .shop-nav-btn.active { background: var(--accent-cyan); color: var(--bg-primary); border-color: var(--accent-cyan); font-weight: bold; box-shadow: var(--shadow-glow-cyan); }
        .shop-nav-btn:disabled { opacity: 0.4; cursor: not-allowed; filter: grayscale(80%); }
        .shop-tier-content { display: none; }
        .shop-tier-content.active { display: block; }

        .shop-item {
            background: linear-gradient(135deg, rgba(36,32,64,0.7), rgba(46,42,74,0.8));
            padding: 12px; border-radius: 8px; margin-bottom: 8px;
            display: grid; grid-template-columns: auto 1fr; gap: 12px; align-items: center;
            border: 1px solid var(--border-color); transition: all 0.3s ease;
        }
        .shop-item:hover { border-color: var(--border-highlight); transform: scale(1.02); }
        .shop-item.disabled { opacity: 0.5; }
        .shop-item-details { display: flex; flex-direction: column; }
        .shop-item-header { display: flex; justify-content: space-between; align-items: center; }
        .shop-item-name { font-weight: bold; color: var(--text-title); font-size: 1.05em; }
        .shop-item-cost { color: var(--accent-gold); font-weight: bold; font-family: var(--font-tech); }
        .shop-item-desc { font-size: 0.9em; color: var(--text-muted); margin-top: 4px; }

        .custom-item-section { border-top: 1px solid var(--border-color); margin-top: 15px; padding-top: 15px; }
        .custom-item-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; align-items: center; margin-bottom: 10px; }
        .custom-item-form-grid .form-group { margin-bottom: 0; }
        .custom-item-form-grid .full-width { grid-column: 1 / -1; }



        /* --- Heroine Title Styles --- */
        .heroine-title-section {
            text-align: center;
            margin-bottom: 20px;
            padding: 10px;
            background: rgba(0,0,0,0.2);
            border-radius: 8px;
            border: 1px solid var(--border-color);
        }
        .heroine-title-name {
            font-family: var(--font-tech);
            font-size: 1.4em;
            font-weight: 700;
            color: var(--accent-cyan);
            text-shadow: var(--shadow-glow-cyan);
            margin-bottom: 8px;
            letter-spacing: 1px;
        }
        .heroine-title-desc {
            font-size: 0.9em;
            color: var(--text-secondary);
            margin: 0;
            padding: 0 10px;
        }
        .heroine-title-origin {
            font-size: 0.8em;
            color: var(--text-muted);
            margin-top: 6px;
            font-style: italic;
        }
        .heroine-title-origin strong {
            color: var(--accent-gold);
        }
    </style>
</head>
<body>
<div class="heroine-status-container">
    <nav class="main-nav">
        <button class="nav-btn active" data-target="panel-system">系统 & USER</button>
        <button class="nav-btn" data-target="panel-heroine">女主角</button>
        <button class="nav-btn" data-target="panel-tools">USER 工具</button>
        <button class="nav-btn" data-target="panel-quests">任务</button>
        <button class="nav-btn" data-target="panel-recognition">认可度</button>
    </nav>

    <div class="main-content-area">
        <!-- Panel 1: 系统 & USER -->
        <div id="panel-system" class="content-panel active">
            <h3 class="section-title">世界信息</h3>
            <div class="info-grid">
                <span class="label">世界:</span><span id="world-name">--</span>
                <span class="label">时间:</span><span id="world-time">--</span>
                <span class="label">位置:</span><span id="world-location">--</span>
                <span class="label">世界观:</span><span id="world-concept">--</span>
                <span class="label">力量体系:</span><span id="world-power-system">--</span>
            </div>
            <h3 class="section-title">USER 信息</h3>
            <div class="info-grid">
                <span class="label">身份:</span><span id="user-identity">--</span>
                <span class="label">存在形式:</span><span id="user-form">--</span>
                <span class="label">契约形式:</span><span id="user-contract">--</span>
            </div>
        </div>

        <!-- Panel 2: 女主角 -->
        <div id="panel-heroine" class="content-panel">
            <div class="heroine-header">
                <span id="heroine-name-main" class="heroine-name">--</span>
                <span id="heroine-points" class="heroine-points">-- 积分</span>
            </div>

            <div id="heroine-title-container" class="heroine-title-section">
                <div id="heroine-title-name">--</div>
                <p id="heroine-title-desc" class="heroine-title-desc">--</p>
                <p id="heroine-title-origin" class="heroine-title-origin"><strong>来源:</strong> --</p>
            </div>


            <h4 class="sub-section-title">基本档案</h4>
            <div class="attributes-grid">
                <div class="attribute-item"><span class="name">年龄</span><span id="heroine-age" class="value">--</span></div>
                <div class="attribute-item"><span class="name">种族</span><span id="heroine-race" class="value">--</span></div>
                <div class="attribute-item"><span class="name">职业</span><span id="heroine-class" class="value">--</span></div>
            </div>
            <h4 class="sub-section-title">外貌与性格</h4>
            <p id="heroine-appearance" class="text-block">--</p>
            <p id="heroine-personality" class="text-block">--</p>
            <h4 class="sub-section-title">身体状态</h4>
            <div class="stat-bar"><div class="bar-label"><span class="label-name">生命值 (HP)</span><span id="hp-value" class="label-value">--/--</span></div><div class="progress-bar-bg"><div id="hp-fill" class="progress-bar-fill"></div></div></div>
            <div class="stat-bar"><div class="bar-label"><span class="label-name">能量值 (MP)</span><span id="mp-value" class="label-value">--/--</span></div><div class="progress-bar-bg"><div id="mp-fill" class="progress-bar-fill"></div></div></div>
            <div class="status-effects-container"><div id="positive-status-list"></div><div id="negative-status-list"></div></div>
            <h4 class="sub-section-title">核心属性</h4>
            <div class="attributes-grid">
                <div class="attribute-item"><span class="name">力量</span><span id="attr-str" class="value">--</span></div><div class="attribute-item"><span class="name">敏捷</span><span id="attr-agi" class="value">--</span></div><div class="attribute-item"><span class="name">体质</span><span id="attr-vit" class="value">--</span></div>
                <div class="attribute-item"><span class="name">智力</span><span id="attr-int" class="value">--</span></div><div class="attribute-item"><span class="name">精神</span><span id="attr-spr" class="value">--</span></div><div class="attribute-item combat-power"><span class="name">战斗力</span><span id="attr-pow" class="value">--</span></div>
            </div>
            <h4 class="sub-section-title">装备</h4>
            <div class="equipment-list">
                <span class="slot">武器:</span><span id="eq-weapon" class="item">--</span>
                <span class="slot">头部:</span><span id="eq-head" class="item">--</span>
                <span class="slot">身体:</span><span id="eq-body" class="item">--</span>
                <span class="slot">腿部:</span><span id="eq-legs" class="item">--</span>
                <span class="slot">饰品:</span><span id="eq-acc" class="item">--</span>
            </div>
            <h4 class="sub-section-title">技能</h4><div id="skills-list" class="dynamic-list"></div>
            <!-- MODIFIED: "道具" changed to "物品栏" -->
            <h4 class="sub-section-title">物品栏</h4><div id="items-list" class="dynamic-list"></div>
        </div>

        <!-- Panel 3: USER 工具 -->
        <div id="panel-tools" class="content-panel">
            <h3 class="section-title">USER 工具</h3>
            <div style="display: flex; flex-direction: column; gap: 15px;">
                <button id="open-task-modal-btn" class="api-btn">发布新任务</button>
                <button id="open-shop-modal-btn" class="api-btn">打开系统商城</button>
            </div>
        </div>

        <!-- Panel 4: 任务 -->
        <div id="panel-quests" class="content-panel">
            <h3 class="section-title">当前任务</h3>
            <div id="quests-list" class="dynamic-list"></div>
        </div>

        <!-- Panel 5: 认可度 -->
        <div id="panel-recognition" class="content-panel">
            <h3 class="section-title">USER认可度</h3>
             <div class="stat-bar" style="margin-top:10px;">
                <div class="bar-label">
                    <span>当前数值</span>
                    <span id="rec-value" class="label-value">-- / 100</span>
                </div>
                <div class="progress-bar-bg"><div id="rec-fill" class="progress-bar-fill"></div></div>
            </div>
             <div style="margin-top: 20px;">
                <div id="rec-display-mode" class="api-controls" style="justify-content: center;">
                    <button id="rec-edit-btn" class="api-btn">编辑认可度</button>
                </div>
                <div id="rec-edit-mode" class="api-controls-edit" style="display: none; flex-direction: column; gap: 15px;">
                    <div style="width: 100%; display: flex; align-items: center; gap: 10px;">
                         <input type="range" id="rec-slider" min="0" max="100" class="api-slider">
                         <span id="rec-slider-value" class="api-slider-value">0</span>
                    </div>
                    <div style="display: flex; gap: 10px;">
                        <button id="rec-confirm-btn" class="api-btn api-btn-confirm">确认修改</button>
                        <button id="rec-cancel-btn" class="api-btn api-btn-cancel">取消</button>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

<!-- Modals -->
<div id="task-modal" class="modal-overlay"><div class="modal-content">
    <div class="modal-header"><h3 class="modal-title">发布新任务</h3><button class="modal-close-btn">&times;</button></div>
    <div class="modal-body">
        <div class="form-group"><label for="task-name">任务名称</label><input type="text" id="task-name" placeholder="例如：【主线】启程之时"></div>
