    function safeTriggerSlash(command) {
        if (typeof triggerSlash === 'function') {
            triggerSlash(command);
            return true;
        } else {
            console.error("triggerSlash function is not available in this environment.");
            alert("错误：无法直接发送指令。 'triggerSlash' 函数未定义，请确认您的酒馆助手环境已正确加载相关插件。");
            return false;
        }
    }

    function _get(obj, path, defaultValue) {
        const pathArray = path.split('.'); let result = obj;
        for (const key of pathArray) { if (result === null || result === undefined) return defaultValue; result = result[key]; }
        return result === undefined ? defaultValue : result;
    }
    function updateField(id, value, suffix = '') { const el = document.getElementById(id); if (el) el.textContent = (value !== undefined && value !== null && value !== '') ? (value + suffix) : '--'; }
    function updateProgressBar(fillId, valueId, current, max) {
        const fill = document.getElementById(fillId); const valueDisp = document.getElementById(valueId);
        if (!fill || !valueDisp) return;
        current = parseFloat(current); max = parseFloat(max);
        if (isNaN(current) || isNaN(max)) { valueDisp.textContent = '--/--'; fill.style.width = '0%'; return; }
        valueDisp.textContent = `${current}/${max}`;
        const percentage = max > 0 ? (current / max) * 100 : 0;
        fill.style.width = `${Math.min(100, Math.max(0, percentage))}%`;
    }
    function renderDynamicList(containerId, items, renderFunc, emptyText) {
        const container = document.getElementById(containerId);
        if (!container) return;
