            content: '';
            position: absolute;
            bottom: 0;
            left: 10%;
            width: 80%;
            height: 3px;
            background: var(--glow-primary);
            box-shadow: 0 0 15px 3px var(--glow-primary);
            opacity: 0;
            transition: var(--transition-fast);
            transform: scaleX(0);
        }
        .nav-button.active:after {
            opacity: 1;
            transform: scaleX(1);
        }


        /* --- 内容区域 --- */
        .card-content { 
            padding: 2.5em; 
            animation: fadeIn 0.6s cubic-bezier(0.165, 0.84, 0.44, 1); 
        }
        .page { display: none; }
        .page.active { display: block; }

        /* --- 表单元素 --- */
        h2 { 
            font-family: var(--font-ui);
            font-size: 2em; 
            color: var(--text-primary); 
            margin-bottom: 1.2em; 
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 2px;
            text-shadow: 0 0 5px var(--glow-secondary), 0 0 10px var(--glow-secondary);
        }

        .form-group { margin-bottom: 2em; position: relative; }

        label { 
            display: block; 
            margin-bottom: 0.8em; 
            color: var(--glow-secondary); 
            font-size: 1.2em; 
            font-weight: 500;
            font-family: var(--font-ui);
            text-transform: uppercase;
            letter-spacing: 1.5px;
        }

        input[type="text"], textarea, select {
            width: 100%;
            padding: 1em 1.5em;
            background: var(--bg-glass);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            color: var(--text-primary);
            font-family: var(--font-main);
            font-size: 1em;
            transition: var(--transition-fast);
            backdrop-filter: blur(5px);
            -webkit-backdrop-filter: blur(5px);
            caret-color: var(--glow-primary);
            box-shadow: inset 0 0 15px rgba(18, 12, 32, 0.5);
        }

        input[type="text"]:focus, textarea:focus, select:focus {
            outline: none;
            border-color: var(--border-highlight);
            box-shadow: 0 0 15px rgba(255, 51, 168, 0.5), inset 0 0 10px rgba(255, 51, 168, 0.1);
        }
        textarea { min-height: 120px; resize: vertical; }

        /* --- 预览面板 --- */
        #worldview-preview, #scene-preview {
            margin-top: 1.5em;
            padding: 1.5em 2em;
            background-color: var(--bg-glass);
            border-radius: 12px;
            border: 1px solid var(--border-color);
            position: relative;
            overflow: hidden;
        }
        /* 预览面板装饰 */
        #worldview-preview::before, #scene-preview::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 50%;
            height: 1px;
            background: linear-gradient(90deg, var(--glow-secondary), transparent);
        }

        #worldview-preview h3, #scene-preview h3 {
            font-family: var(--font-ui);
            font-size: 1.4em;
            color: var(--glow-secondary);
            margin-bottom: 0.8em;
            padding-bottom: 0.8em;
            border-bottom: 1px solid var(--border-color);
            text-transform: uppercase;
        }

        #worldview-preview p, #scene-preview p { 
            white-space: pre-wrap; 
            line-height: 1.6; 
            color: var(--text-secondary); 
            font-size: 0.95em;
        }

        /* --- 最终确认面板 --- */
        #summary-panel {
            min-height: 400px;
            background-color: rgba(10, 5, 20, 0.8);
            color: #00e5ff;
            font-family: 'Consolas', 'Monaco', monospace;
            font-size: 0.9em;
            border: 1px solid var(--border-color);
            border-radius: 12px;
            box-shadow: inset 0 0 20px rgba(0,0,0,0.5);
            line-height: 1.5;
        }

        /* --- 按钮 --- */
        .button-container { text-align: center; margin-top: 2em; }

        .btn {
            padding: 1em 3em;
            background: linear-gradient(45deg, var(--glow-accent), var(--glow-primary));
            color: #fff;
            border: 1px solid var(--glow-primary);
            border-radius: 50px;
            cursor: pointer;
            font-family: var(--font-ui);
            font-size: 1.2em;
            font-weight: 700;
            transition: var(--transition-medium);
            box-shadow: 0 0 15px rgba(255, 51, 168, 0.4), 0 0 25px rgba(157, 62, 255, 0.3);
            text-shadow: 0 0 5px rgba(255,255,255,0.5);
            text-transform: uppercase;
            letter-spacing: 2px;
            position: relative;
            overflow: hidden;
        }
        .btn::before { /* 悬停扫光效果 */
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: linear-gradient(transparent, rgba(255, 255, 255, 0.2), transparent);
            transform: rotate(45deg);
            transition: all 0.5s;
            opacity: 0;
        }
        .btn:hover::before {
            left: 100%;
            opacity: 1;
            transition: left 0.8s;
        }

        .btn:hover {
            transform: translateY(-5px) scale(1.05);
            box-shadow: 0 0 25px rgba(255, 51, 168, 0.7), 0 0 45px rgba(157, 62, 255, 0.5);
        }

        .btn#generate-btn {
            animation: pulse-glow 4s infinite ease-in-out;
        }

        .btn-secondary {
            background: transparent;
            color: var(--glow-secondary);
            border: 1px solid var(--glow-secondary);
            box-shadow: 0 0 15px rgba(0, 229, 255, 0.3);
        }
        .btn-secondary:hover {
            background: rgba(0, 229, 255, 0.1);
            color: #fff;
            border-color: var(--glow-secondary);
            box-shadow: 0 0 20px rgba(0, 229, 255, 0.5);
            text-shadow: 0 0 10px var(--glow-secondary);
        }
    </style>
