<div id="card-container">
    <nav class="card-nav">
        <button class="nav-button active" onclick="showPage('page-worldview', this)">1. 世界观设定</button>
        <button class="nav-button" onclick="showPage('page-protagonists', this)">2. 主角设定</button>
        <button class="nav-button" onclick="showPage('page-scene', this)">3. 开局场景</button>
        <button class="nav-button" onclick="showPage('page-summary', this)">4. 最终确认</button>
    </nav>

    <div class="card-content">
        <!-- Page 1: Worldview -->
        <div id="page-worldview" class="page active">
            <h2>🌍 选择世界观</h2>
            <div class="form-group">
                <label for="worldview-select">从预设模板中选择，或创建您的专属世界</label>
                <select id="worldview-select" onchange="handleWorldviewChange()"></select>
            </div>
            <div id="worldview-preview"></div>
            <div id="custom-worldview-fields" style="display: none;">
                <div class="form-group"><label for="worldview-custom-name">世界观名称</label><input type="text" id="worldview-custom-name" oninput="updateCustomWorldview()"></div>
                <div class="form-group"><label for="worldview-custom-desc">世界观简介</label><textarea id="worldview-custom-desc" oninput="updateCustomWorldview()"></textarea></div>
                <div class="form-group"><label for="worldview-custom-power">力量体系说明</label><textarea id="worldview-custom-power" oninput="updateCustomWorldview()"></textarea></div>
            </div>
        </div>

        <!-- Page 2: Protagonists -->
        <div id="page-protagonists" class="page">
            <h2>👤 设定主角</h2>
            <div class="button-container" style="margin-bottom: 2em;">
                <button class="btn btn-secondary" onclick="applyTemplate()">✨ 一键应用『天使与傲娇大小姐』模板</button>
            </div>
            <div class="form-group">
                <label for="user-identity">您的身份 (USER)</label>
                <textarea id="user-identity" placeholder="例如：寄宿在她识海中的灵魂绑定系统，或一把拥有自我意识的神剑..." oninput="updateConfig('userCharacter.identity', this.value)"></textarea>
            </div>
            <div class="form-group">
                <label for="heroine-name">女主角姓名</label>
                <input type="text" id="heroine-name" placeholder="为您的女主角取一个名字" oninput="updateConfig('heroineCharacter.name', this.value)">
            </div>
            <div class="form-group">
                <label for="heroine-background">女主角背景故事</label>
                <textarea id="heroine-background" placeholder="她的出身、经历、性格特点等。" oninput="updateConfig('heroineCharacter.background', this.value)"></textarea>
            </div>
            <div class="form-group">
                <label for="heroine-goal">女主角初始目标</label>
                <textarea id="heroine-goal" placeholder="故事开始时，她最想做成的事是什么？" oninput="updateConfig('heroineCharacter.goal', this.value)"></textarea>
            </div>
        </div>

        <!-- Page 3: Scene -->
        <div id="page-scene" class="page">
            <h2>🎬 设定开局场景</h2>
            <div class="form-group">
                <label for="scene-select">选择场景氛围</label>
                <select id="scene-select" onchange="handleSceneChange()"></select>
            </div>
            <div id="scene-preview"></div>
            <div class="form-group">
                <label for="scene-desc">自定义场景描述</label>
                <textarea id="scene-desc" placeholder="请在此详细描述故事开始的瞬间，包括环境、角色的状态和正在发生的事。" oninput="updateConfig('scene.description', this.value)"></textarea>
            </div>
        </div>

        <!-- Page 4: Summary -->
        <div id="page-summary" class="page">
            <h2>✅ 最终设定总览</h2>
            <div class="form-group">
                <label>请确认您的完整设定（JSON格式）</label>
                <textarea id="summary-panel" readonly></textarea>
            </div>
            <div class="button-container">
                <button class="btn" id="generate-btn" onclick="generateCommand()">开启新世界</button>
            </div>
        </div>
    </div>
</div>

