        <div class="form-group"><label for="task-type">任务类型</label><input type="text" id="task-type" placeholder="主线 / 支线 / 日常"></div>
        <div class="form-group"><label for="task-desc">任务说明</label><textarea id="task-desc" placeholder="任务的背景故事和描述..."></textarea></div>
        <div class="form-group"><label for="task-target">任务目标</label><textarea id="task-target" placeholder="需要完成的具体事项..."></textarea></div>
        <div class="form-group"><label for="task-reward">任务奖励</label><input type="text" id="task-reward" placeholder="例如：积分 +50, 初级治疗药水x1"></div>
    </div>
    <div class="modal-footer">
        <button id="send-task-btn" class="api-btn">直接发送任务</button>
        <button id="copy-task-btn" class="api-btn api-btn-confirm">复制任务指令</button>
    </div>
</div></div>

<div id="shop-modal" class="modal-overlay"><div class="modal-content">
    <div class="modal-header"><h3 class="modal-title">系统商城</h3><button class="modal-close-btn">&times;</button></div>
