                <div class="form-group"><label for="custom-item-type">类型</label><input type="text" id="custom-item-type"></div>
                <div class="form-group"><label for="custom-item-cost">费用</label><input type="number" id="custom-item-cost" min="0"></div>
                <div class="form-group full-width"><label for="custom-item-desc">描述</label><textarea id="custom-item-desc" rows="2"></textarea></div>
