        </div>
    </div>
    <div class="modal-footer">
        <button id="send-shop-btn" class="api-btn">直接展示商城</button>
        <button id="copy-purchase-btn" class="api-btn api-btn-confirm">复制商城配置指令</button>
    </div>
</div></div>

