            --transition-medium: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
        }

        /* --- 关键帧动画 --- */
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(15px) scale(0.98); }
            to { opacity: 1; transform: translateY(0) scale(1); }
        }

        @keyframes glitch {
            0%, 100% { clip-path: inset(0 0 0 0); }
            20% { clip-path: inset(40% 0 40% 0); }
            40% { clip-path: inset(20% 0 60% 0); }
            60% { clip-path: inset(70% 0 10% 0); }
            80% { clip-path: inset(50% 0 30% 0); }
        }

        @keyframes scanline {
            0% { transform: translateY(-100%); }
            100% { transform: translateY(100%); }
        }

        @keyframes pulse-glow {
            0%, 100% { box-shadow: 0 0 20px 5px rgba(255, 51, 168, 0), inset 0 0 10px rgba(255, 51, 168, 0); }
            50% { box-shadow: 0 0 35px 10px rgba(255, 51, 168, 0.3), inset 0 0 20px rgba(255, 51, 168, 0.2); }
        }

        /* --- 基础与重置 --- */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            /* 严格遵守要求：BODY背景透明 */
            background-color: transparent;
            font-family: var(--font-main);
            color: var(--text-primary);
            line-height: 1.7;
            font-size: 16px;
            padding: 2em 1em;
            display: flex;
            justify-content: center;
            align-items: flex-start;
            overflow: hidden; /* 防止装饰元素溢出 */
        }

        /* --- 主容器 & 装饰 --- */
        #card-container {
            width: 100%;
            max-width: 800px;
            background: var(--bg-dark-transparent);
            border-radius: 20px;
            border: 1px solid var(--border-color);
            box-shadow: 0 0 40px rgba(0, 229, 255, 0.2), 0 0 60px rgba(255, 51, 168, 0.15), inset 0 0 20px rgba(18, 12, 32, 0.8);
            overflow: hidden;
            display: flex;
            flex-direction: column;
            position: relative;
            backdrop-filter: blur(12px) saturate(150%);
            -webkit-backdrop-filter: blur(12px) saturate(150%);
        }

        /* 装饰：扫描线动画遮罩 */
        #card-container::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(rgba(18, 12, 32, 0.1) 50%, rgba(0, 229, 255, 0.05) 50%);
            background-size: 100% 4px;
            opacity: 0.3;
            pointer-events: none;
        }

        /* 装饰：角落UI元素 */
        #card-container::after {
            content: 'SYS_INTERFACE v3.0 // ENHANCED_EDITION';
            position: absolute;
            bottom: 8px;
            right: 15px;
            font-family: var(--font-ui);
            font-size: 0.7em;
            color: var(--glow-secondary);
            opacity: 0.4;
            letter-spacing: 2px;
        }

        /* --- 导航栏 --- */
        .card-nav {
            display: flex;
            background-color: rgba(30, 20, 55, 0.5);
            border-bottom: 1px solid var(--border-color);
            backdrop-filter: blur(5px);
            -webkit-backdrop-filter: blur(5px);
            padding: 0 1em;
        }

        .nav-button {
            padding: 1em 1.5em;
            border: none;
            background: transparent;
            color: var(--text-secondary);
            font-family: var(--font-ui);
            font-size: 1.1em;
            font-weight: 600;
            cursor: pointer;
            transition: var(--transition-medium);
            position: relative;
            clip-path: polygon(10% 0, 100% 0, 90% 100%, 0% 100%);
            text-transform: uppercase;
            letter-spacing: 1px;
        }
        .nav-button:hover {
            color: var(--text-primary);
            background: rgba(255, 51, 168, 0.1);
            text-shadow: 0 0 10px var(--glow-primary);
        }
        .nav-button.active {
            color: var(--glow-primary);
            background: linear-gradient(to top, rgba(255, 51, 168, 0.2), transparent);
            text-shadow: 0 0 15px var(--glow-primary);
        }
        .nav-button:after { /* 活动状态指示器 */
            content: '';
            position: absolute;
            bottom: 0;
            left: 10%;
            width: 80%;
            height: 3px;
            background: var(--glow-primary);
            box-shadow: 0 0 15px 3px var(--glow-primary);
            opacity: 0;
            transition: var(--transition-fast);
            transform: scaleX(0);
        }
        .nav-button.active:after {
            opacity: 1;
            transform: scaleX(1);
        }


        /* --- 内容区域 --- */
        .card-content { 
            padding: 2.5em; 
            animation: fadeIn 0.6s cubic-bezier(0.165, 0.84, 0.44, 1); 
        }
        .page { display: none; }
        .page.active { display: block; }

        /* --- 表单元素 --- */
        h2 { 
            font-family: var(--font-ui);
            font-size: 2em; 
            color: var(--text-primary); 
            margin-bottom: 1.2em; 
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 2px;
            text-shadow: 0 0 5px var(--glow-secondary), 0 0 10px var(--glow-secondary);
        }

        .form-group { margin-bottom: 2em; position: relative; }

        label { 
            display: block; 
            margin-bottom: 0.8em; 
            color: var(--glow-secondary); 
            font-size: 1.2em; 
            font-weight: 500;
            font-family: var(--font-ui);
            text-transform: uppercase;
            letter-spacing: 1.5px;
        }

        input[type="text"], textarea, select {
            width: 100%;
            padding: 1em 1.5em;
            background: var(--bg-glass);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            color: var(--text-primary);
            font-family: var(--font-main);
            font-size: 1em;
            transition: var(--transition-fast);
            backdrop-filter: blur(5px);
            -webkit-backdrop-filter: blur(5px);
            caret-color: var(--glow-primary);
            box-shadow: inset 0 0 15px rgba(18, 12, 32, 0.5);
        }

        input[type="text"]:focus, textarea:focus, select:focus {
            outline: none;
            border-color: var(--border-highlight);
            box-shadow: 0 0 15px rgba(255, 51, 168, 0.5), inset 0 0 10px rgba(255, 51, 168, 0.1);
        }
        textarea { min-height: 120px; resize: vertical; }

        /* --- 预览面板 --- */
        #worldview-preview, #scene-preview {
            margin-top: 1.5em;
            padding: 1.5em 2em;
            background-color: var(--bg-glass);
            border-radius: 12px;
            border: 1px solid var(--border-color);
            position: relative;
            overflow: hidden;
        }
        /* 预览面板装饰 */
        #worldview-preview::before, #scene-preview::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 50%;
            height: 1px;
            background: linear-gradient(90deg, var(--glow-secondary), transparent);
        }

        #worldview-preview h3, #scene-preview h3 {
            font-family: var(--font-ui);
            font-size: 1.4em;
            color: var(--glow-secondary);
            margin-bottom: 0.8em;
            padding-bottom: 0.8em;
            border-bottom: 1px solid var(--border-color);
            text-transform: uppercase;
        }

        #worldview-preview p, #scene-preview p { 
            white-space: pre-wrap; 
            line-height: 1.6; 
            color: var(--text-secondary); 
            font-size: 0.95em;
        }

        /* --- 最终确认面板 --- */
        #summary-panel {
            min-height: 400px;
            background-color: rgba(10, 5, 20, 0.8);
            color: #00e5ff;
            font-family: 'Consolas', 'Monaco', monospace;
            font-size: 0.9em;
            border: 1px solid var(--border-color);
            border-radius: 12px;
            box-shadow: inset 0 0 20px rgba(0,0,0,0.5);
            line-height: 1.5;
        }

        /* --- 按钮 --- */
        .button-container { text-align: center; margin-top: 2em; }

        .btn {
            padding: 1em 3em;
            background: linear-gradient(45deg, var(--glow-accent), var(--glow-primary));
            color: #fff;
            border: 1px solid var(--glow-primary);
            border-radius: 50px;
            cursor: pointer;
            font-family: var(--font-ui);
            font-size: 1.2em;
            font-weight: 700;
            transition: var(--transition-medium);
            box-shadow: 0 0 15px rgba(255, 51, 168, 0.4), 0 0 25px rgba(157, 62, 255, 0.3);
            text-shadow: 0 0 5px rgba(255,255,255,0.5);
            text-transform: uppercase;
            letter-spacing: 2px;
            position: relative;
            overflow: hidden;
        }
        .btn::before { /* 悬停扫光效果 */
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: linear-gradient(transparent, rgba(255, 255, 255, 0.2), transparent);
            transform: rotate(45deg);
            transition: all 0.5s;
            opacity: 0;
        }
        .btn:hover::before {
            left: 100%;
            opacity: 1;
            transition: left 0.8s;
        }

        .btn:hover {
            transform: translateY(-5px) scale(1.05);
            box-shadow: 0 0 25px rgba(255, 51, 168, 0.7), 0 0 45px rgba(157, 62, 255, 0.5);
        }

        .btn#generate-btn {
            animation: pulse-glow 4s infinite ease-in-out;
        }

        .btn-secondary {
            background: transparent;
            color: var(--glow-secondary);
            border: 1px solid var(--glow-secondary);
            box-shadow: 0 0 15px rgba(0, 229, 255, 0.3);
        }
        .btn-secondary:hover {
            background: rgba(0, 229, 255, 0.1);
            color: #fff;
            border-color: var(--glow-secondary);
            box-shadow: 0 0 20px rgba(0, 229, 255, 0.5);
            text-shadow: 0 0 10px var(--glow-secondary);
        }
    </style>
</head>
<body>

<div id="card-container">
    <nav class="card-nav">
        <button class="nav-button active" onclick="showPage('page-worldview', this)">1. 世界观设定</button>
        <button class="nav-button" onclick="showPage('page-protagonists', this)">2. 主角设定</button>
        <button class="nav-button" onclick="showPage('page-scene', this)">3. 开局场景</button>
        <button class="nav-button" onclick="showPage('page-summary', this)">4. 最终确认</button>
    </nav>

    <div class="card-content">
        <!-- Page 1: Worldview -->
        <div id="page-worldview" class="page active">
            <h2>🌍 选择世界观</h2>
            <div class="form-group">
                <label for="worldview-select">从预设模板中选择，或创建您的专属世界</label>
                <select id="worldview-select" onchange="handleWorldviewChange()"></select>
            </div>
            <div id="worldview-preview"></div>
            <div id="custom-worldview-fields" style="display: none;">
                <div class="form-group"><label for="worldview-custom-name">世界观名称</label><input type="text" id="worldview-custom-name" oninput="updateCustomWorldview()"></div>
                <div class="form-group"><label for="worldview-custom-desc">世界观简介</label><textarea id="worldview-custom-desc" oninput="updateCustomWorldview()"></textarea></div>
                <div class="form-group"><label for="worldview-custom-power">力量体系说明</label><textarea id="worldview-custom-power" oninput="updateCustomWorldview()"></textarea></div>
            </div>
        </div>

        <!-- Page 2: Protagonists -->
        <div id="page-protagonists" class="page">
            <h2>👤 设定主角</h2>
            <div class="button-container" style="margin-bottom: 2em;">
                <button class="btn btn-secondary" onclick="applyTemplate()">✨ 一键应用『天使与傲娇大小姐』模板</button>
            </div>
            <div class="form-group">
                <label for="user-identity">您的身份 (USER)</label>
                <textarea id="user-identity" placeholder="例如：寄宿在她识海中的灵魂绑定系统，或一把拥有自我意识的神剑..." oninput="updateConfig('userCharacter.identity', this.value)"></textarea>
            </div>
            <div class="form-group">
                <label for="heroine-name">女主角姓名</label>
                <input type="text" id="heroine-name" placeholder="为您的女主角取一个名字" oninput="updateConfig('heroineCharacter.name', this.value)">
            </div>
            <div class="form-group">
                <label for="heroine-background">女主角背景故事</label>
                <textarea id="heroine-background" placeholder="她的出身、经历、性格特点等。" oninput="updateConfig('heroineCharacter.background', this.value)"></textarea>
            </div>
            <div class="form-group">
                <label for="heroine-goal">女主角初始目标</label>
                <textarea id="heroine-goal" placeholder="故事开始时，她最想做成的事是什么？" oninput="updateConfig('heroineCharacter.goal', this.value)"></textarea>
            </div>
        </div>

        <!-- Page 3: Scene -->
        <div id="page-scene" class="page">
            <h2>🎬 设定开局场景</h2>
            <div class="form-group">
                <label for="scene-select">选择场景氛围</label>
                <select id="scene-select" onchange="handleSceneChange()"></select>
            </div>
            <div id="scene-preview"></div>
            <div class="form-group">
                <label for="scene-desc">自定义场景描述</label>
                <textarea id="scene-desc" placeholder="请在此详细描述故事开始的瞬间，包括环境、角色的状态和正在发生的事。" oninput="updateConfig('scene.description', this.value)"></textarea>
            </div>
        </div>

        <!-- Page 4: Summary -->
        <div id="page-summary" class="page">
            <h2>✅ 最终设定总览</h2>
            <div class="form-group">
                <label>请确认您的完整设定（JSON格式）</label>
                <textarea id="summary-panel" readonly></textarea>
            </div>
            <div class="button-container">
                <button class="btn" id="generate-btn" onclick="generateCommand()">开启新世界</button>
            </div>
        </div>
    </div>
</div>

<script>
// --- DATABASE ---
const worldviewsDB = [
    { name: "艾瑞斯大陆 (传统西幻)", description: "一个剑与魔法共存的幻想世界。神明在云端俯瞰，深渊在地下觊觎，人类、精灵、矮人等多种族在大陆上建立各自的文明与王国。古老的预言、失落的遗迹和巨龙的咆哮是冒险者们永恒的旋律。", powerSystem: "本世界的力量以'源力'为基础，通过精神共鸣引导，显化为战士的'斗气'或法师的'魔法'。所有超凡力量的强度，都可以通过魔法水晶精确测量为'战斗力'数值。\n\n【战斗力等级划分】:\n- 黑铁阶 (战斗力 1 ~ 99): 普通士兵与初学者。\n- 青铜阶 (战斗力 100 ~ 499): 正式踏入超凡门槛的战士或法师学徒。\n- 白银阶 (战斗力 500 ~ 1,999): 经验丰富的冒险者，军队中的精英。\n- 黄金阶 (战斗力 2,000 ~ 9,999): 一方强者，足以担任城邦守护者。\n- 传奇阶 (战斗力 10,000 ~ 49,999): 名震大陆的英雄人物。\n- 圣域阶 (战斗力 50,000+): 如同在世神明，千年难遇。" },
    { name: "阿卡迪亚世界 (日式西幻)", description: "这是一个存在着'魔王'与'勇者'传说的世界。魔力（Mana）是构成万物的能量，天赋异禀者能将其引导为强大的魔法或剑技。为了对抗从深渊涌现的魔物，人类建立了'冒险者公会'。", powerSystem: "本世界的力量核心是'魔力'的质与量。冒险者公会使用'鉴定水晶'，将其综合实力换算为直观的'战斗力'数值。\n\n【战斗力冒险者等级划分】:\n- F级 (战斗力 1 ~ 150): 新手冒险者。\n- E级 (战斗力 151 ~ 500): 脱离菜鸟阶段。\n- D级 (战斗力 501 ~ 1,500): 合格的冒险者。\n- C级 (战斗力 1,501 ~ 5,000): 中坚力量。\n- B级 (战斗力 5,001 ~ 15,000): 精英冒险者。\n- A级 (战斗力 15,001 ~ 50,000): 国家级英雄。\n- S级 (战斗力 50,001+): 人类顶点。\n- 规格外 (战斗力 无法测定): 勇者与魔王。" },
    { name: "神州浩土 (玄幻修仙)", description: "此界广袤无垠，亿万生灵追求长生大道。宗门林立，圣地传承万古。修士们逆天而行，夺天地之造化，历经磨难与天劫，只为超脱轮回。", powerSystem: "体系核心为'灵气'。修士的'灵压'强度可通过'测灵石'量化为'战斗力'。境界是生命层次的跃迁。\n\n【战斗力境界划分】:\n- 炼气境 (战斗力 1 ~ 50)\n- 筑基境 (战斗力 51 ~ 200)\n- 金丹境 (战斗力 201 ~ 1,000)\n- 元婴境 (战斗力 1,001 ~ 5,000)\n- 化神境 (战斗力 5,001 ~ 20,000)\n- 返虚境 (战斗力 20,001 ~ 100,000)\n- 大乘境 (战斗力 100,001+)" },
    { name: "无名江湖 (武侠)", description: "皇权与江湖并存的世界。朝廷设有锦衣卫维系法度，而江湖中则有各大门派。武者们为了一本秘籍、一把神兵，掀起无数腥风血雨。", powerSystem: "核心为'内力'与'招式'。江湖中'天机阁'制造的'气血仪'可以通过测量武者的内力浑厚程度和气血强度，得出一个综合'战斗力'指数。\n\n【战斗力等级划分】:\n- 不入流 (战斗力 1 ~ 9)\n- 三流高手 (战斗力 10 ~ 50)\n- 二流高手 (战斗力 51 ~ 200)\n- 一流高手 (战斗力 201 ~ 1,000)\n- 绝顶高手 (战斗力 1,001 ~ 5,000)\n- 宗师 (战斗力 5,001+)" },
    { name: "新京市 • 2077 (赛博科幻)", description: "一座被巨型企业联合体所统治的未来都市。科技高度发达，义体改造、网络潜入是常态。在霓虹灯与全息广告牌照耀不到的角落，是底层民众挣扎求生的残酷现实。", powerSystem: "力量来源于'科技'与'资源'。城市安保系统和中间人会根据目标的义体等级、武器装备和过往战绩，评估出一个'综合战斗力'。\n\n【战斗力等级划分】:\n- 街头杂鱼 (战斗力 1 ~ 100)\n- 边缘行者 (战斗力 101 ~ 500)\n- 专业打手 (战斗力 501 ~ 2,500)\n- 都市传奇 (战斗力 2,501 ~ 10,000)\n- 最终兵器 (战斗力 10,001+)" },
    { 
        name: "玄君秘境 (中式克苏鲁)", 
