];
const scenesDB = [
    { atmosphere: "轻松日常", description: "阳光透过窗格，洒在房间里铺着天鹅绒的地毯上。空气中弥漫着少女闺房特有的馨香与淡淡的书卷气。" },
    { atmosphere: "紧张对峙", description: "冰冷的雨水冲刷着小巷的石板路。她面对着的敌人，呼吸凝重。" },
    { atmosphere: "史诗开幕", description: "在骸骨之上，她缓缓举起了手中的剑，吟唱起决定世界命运的祷文。" },
