];
const templateData = {
    user: { identity: "一个天使灵体，平时寄宿在女主角的灵魂深处。{{user}}的使命是引导她，保护她，并见证她的成长。{{user}}可以与她进行灵魂对话，也可以显化出Q版实体在物质世界活动。" },
