        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        document.getElementById(pageId).classList.add('active');
        document.querySelectorAll('.nav-button').forEach(b => b.classList.remove('active'));
        element.classList.add('active');
        updateSummary();
    }

    // --- WORLDVIEW LOGIC ---
    function populateWorldviewSelect() {
        const select = document.getElementById('worldview-select');
        worldviewsDB.forEach((world, index) => {
            select.innerHTML += `<option value="${index}">${world.name}</option>`;
        });
        select.innerHTML += `<option value="custom">USER自定义...</option>`;
    }
    function handleWorldviewChange() {
        const select = document.getElementById('worldview-select');
        const preview = document.getElementById('worldview-preview');
        const customFields = document.getElementById('custom-worldview-fields');
        if (select.value === 'custom') {
            preview.style.display = 'none';
            customFields.style.display = 'block';
            updateCustomWorldview();
        } else {
            preview.style.display = 'block';
            customFields.style.display = 'none';
            const selectedWorld = worldviewsDB[parseInt(select.value)];
            userConfig.worldview = { name: selectedWorld.name, "世界观": selectedWorld.description, "力量体系": selectedWorld.powerSystem };
            preview.innerHTML = `<h3>${selectedWorld.name}</h3><p><strong>简介:</strong>\n${selectedWorld.description}</p><hr style="margin: 1em 0; border: none; border-top: 1px solid var(--border-color);"><p><strong>力量体系:</strong>\n${selectedWorld.powerSystem}</p>`;
