    }

    // --- SCENE LOGIC ---
    function populateSceneSelect() {
        const select = document.getElementById('scene-select');
        scenesDB.forEach((scene, index) => {
            select.innerHTML += `<option value="${index}">${scene.atmosphere}</option>`;
        });
    }
    function handleSceneChange() {
        const select = document.getElementById('scene-select');
        const preview = document.getElementById('scene-preview');
        const descInput = document.getElementById('scene-desc');
        const selectedScene = scenesDB[parseInt(select.value)];

        userConfig.scene = { atmosphere: selectedScene.atmosphere, description: selectedScene.description };
        descInput.value = selectedScene.description;
        preview.innerHTML = `<h3>氛围: ${selectedScene.atmosphere}</h3><p>${selectedScene.description}</p>`;
        updateSummary();
    }

    // --- TEMPLATE LOGIC ---
    function applyTemplate() {
        // Apply data to userConfig
        updateConfig('userCharacter.identity', templateData.user.identity);
        updateConfig('heroineCharacter.name', templateData.heroine.name);
        updateConfig('heroineCharacter.background', templateData.heroine.background);
        updateConfig('heroineCharacter.goal', templateData.heroine.goal);

        // Apply data to form fields
        document.getElementById('user-identity').value = templateData.user.identity;
        document.getElementById('heroine-name').value = templateData.heroine.name;
        document.getElementById('heroine-background').value = templateData.heroine.background;
        document.getElementById('heroine-goal').value = templateData.heroine.goal;

        // Apply scene data
        const sceneSelect = document.getElementById('scene-select');
        const sceneIndex = scenesDB.findIndex(s => s.atmosphere === templateData.scene.atmosphere);
        if (sceneIndex !== -1) {
            sceneSelect.value = sceneIndex;
            handleSceneChange(); // This also updates config and description field
        }
        document.getElementById('scene-desc').value = templateData.scene.description;
        updateConfig('scene.description', templateData.scene.description);

    }

    // --- CONFIG & SUMMARY LOGIC ---
    function updateConfig(path, value) {
        const keys = path.split('.');
        let current = userConfig;
        for (let i = 0; i < keys.length - 1; i++) { current = current[keys[i]]; }
        current[keys[keys.length - 1]] = value;
        updateSummary();
    }
    function updateSummary() {
        const finalConfig = {
            "世界": userConfig.worldview,
            "USER": userConfig.userCharacter,
            "女主角": userConfig.heroineCharacter,
            "开局场景": userConfig.scene
        };
        document.getElementById('summary-panel').value = JSON.stringify(finalConfig, null, 2);
    }

    function generateCommand() {
        const finalJsonString = document.getElementById('summary-panel').value;
        const btn = document.getElementById('generate-btn');
        const commandString = `/send ${finalJsonString} |/trigger`;
        if (typeof triggerSlash === 'function') {
            triggerSlash(commandString); 
            btn.textContent = '指令已发送!';
            setTimeout(() => { btn.textContent = '开启新世界'; }, 2000);
        } else {
            console.log("--- 生成的指令内容 ---");
            console.log(commandString);
            alert("指令已生成，请在浏览器开发者工具的控制台中查看。");
        }
    }

    // --- INITIALIZATION ---
    document.addEventListener('DOMContentLoaded', () => {
        populateWorldviewSelect();
        handleWorldviewChange();
        populateSceneSelect();
        handleSceneChange();
    });
</script>

</body>
</html>
