<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>系统任务</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=M+PLUS+Rounded+1c:wght@400;700;800&display=swap');

        body {
            font-family: 'M PLUS Rounded 1c', sans-serif;
            /* No background for body */
        }

        .task-board-container {
            width: 100%;
            max-width: 500px;
            margin: 30px auto;
            border-radius: 20px;
            background: linear-gradient(160deg, #2a2c40, #1f2238);
            border: 2px solid rgba(190, 170, 255, 0.3);
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4), 0 0 25px rgba(0, 220, 255, 0.1);
            padding: 30px;
            color: #e8e4ff;
            position: relative;
            overflow: hidden;
            animation: board-appear 1s cubic-bezier(0.25, 1, 0.5, 1) forwards;
            transition: transform 0.4s ease, box-shadow 0.4s ease; /* NEW: Hover effect for the whole card */
        }
        .task-board-container:hover {
            transform: translateY(-10px);
            box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5), 0 0 40px rgba(255, 128, 192, 0.3);
            border-color: rgba(255, 128, 192, 0.5);
        }

        @keyframes board-appear {
            from { opacity: 0; transform: perspective(1000px) rotateX(-15deg) scale(0.95); }
            to { opacity: 1; transform: perspective(1000px) rotateX(0deg) scale(1); }
        }

        .board-background-glow {
            position: absolute; top: 50%; left: 50%;
            width: 80%; height: 80%;
            transform: translate(-50%, -50%);
            background: radial-gradient(circle, rgba(0, 220, 255, 0.15) 0%, transparent 70%);
            animation: pulse-glow 6s infinite alternate;
        }
        @keyframes pulse-glow {
            from { opacity: 0.8; transform: translate(-50%, -50%) scale(0.9); }
            to { opacity: 1; transform: translate(-50%, -50%) scale(1.1); }
        }

        .corner-decoration {
            position: absolute; width: 30px; height: 30px;
            border-style: solid; border-color: rgba(190, 170, 255, 0.5);
            transition: all 0.4s ease; /* NEW: Hover transition for corners */
        }
        .corner-tl { top: 15px; left: 15px; border-width: 2px 0 0 2px; }
        .corner-tr { top: 15px; right: 15px; border-width: 2px 2px 0 0; }
        .corner-bl { bottom: 15px; left: 15px; border-width: 0 0 2px 2px; }
        .corner-br { bottom: 15px; right: 15px; border-width: 0 2px 2px 0; }

        .task-board-container:hover .corner-decoration {
            width: 40px; height: 40px;
            border-color: #ff80c0;
        }

        /* --- WINGS REMOVED --- */

        .task-content-wrapper {
            position: relative;
            z-index: 1;
            display: flex;
            flex-direction: column;
            gap: 20px;
            text-align: left;
        }

        .task-header {
            text-align: center;
        }
        .task-type-tag {
            display: inline-block;
            background: rgba(0, 220, 255, 0.1);
            border: 1px solid rgba(0, 220, 255, 0.3);
            color: #00dcff;
            padding: 4px 12px;
            border-radius: 15px;
            font-size: 0.8em;
            font-weight: 700;
            margin-bottom: 10px;
            transition: all 0.3s ease; /* NEW: Hover effect for tag */
        }
        .task-header:hover .task-type-tag {
            background: rgba(0, 220, 255, 0.2);
            transform: scale(1.1);
        }

        .task-name-title {
            font-size: 2.2em;
            font-weight: 800;
            color: #fff;
            text-shadow: 0 0 10px #ff80c0, 0 0 20px #ff80c0;
            transition: text-shadow 0.4s ease; /* NEW: Hover effect for title */
        }
        .task-board-container:hover .task-name-title {
            text-shadow: 0 0 15px #ff80c0, 0 0 30px #ff80c0, 0 0 50px #00dcff;
        }

        .sparkle-divider {
            display: flex; justify-content: center; align-items: center;
            gap: 15px; color: #ffd700; text-shadow: 0 0 8px #ffd700;
            margin: 10px 0;
        }
        .sparkle-divider .line {
            flex-grow: 1; height: 1px;
            background: linear-gradient(to right, transparent, rgba(255, 215, 0, 0.5), transparent);
        }
        .sparkle-divider .sparkle {
            font-size: 1.5em; animation: sparkle-spin 4s infinite linear;
            transition: transform 0.3s ease; /* NEW: Hover effect for sparkle */
        }
        .task-board-container:hover .sparkle {
            transform: scale(1.5);
        }
        @keyframes sparkle-spin { to { transform: rotate(360deg); } }

        .task-section {
            background: rgba(0,0,0,0.2);
            padding: 15px;
            border-radius: 10px;
            border-left: 3px solid #00dcff;
            transition: all 0.3s ease; /* NEW: Hover effect for sections */
        }
        .task-section:hover {
            background: rgba(0,0,0,0.3);
            border-left-color: #ff80c0;
            transform: translateX(5px);
        }

        .section-label {
            font-size: 1.1em;
            font-weight: 700;
            color: #8a99e4;
            display: flex;
            align-items: center;
            gap: 8px;
            margin-bottom: 10px;
        }
        .section-content {
            font-size: 0.95em;
            line-height: 1.8;
            color: #c0c8f0;
        }
        .section-content ul {
            list-style: none;
            padding: 0;
            margin: 0;
            display: flex;
            flex-direction: column;
            gap: 8px;
        }
        .section-content li {
            background: rgba(0,0,0,0.15);
            padding: 8px 12px;
            border-radius: 6px;
            transition: background-color 0.3s, padding-left 0.3s; /* NEW: Hover effect for list items */
        }
        .section-content li:hover {
            background-color: rgba(255, 128, 192, 0.1);
            padding-left: 20px;
        }
